    if isinstance(value, bool) or not isinstance(value, float):
        raise TypeError(
            "%s 必须是 float，得到 %s" % (name, type(value).__name__)
        )
    if not math.isfinite(value):
        raise ValueError("%s 含有非有限值（NaN/inf）" % name)


