    x_shape = _shape_of(x, 4, "x")
    if x_shape[1:] != (1, 2, 2):
        raise ValueError("x 的形状必须为 [N][1][2][2]")
    if x_shape[0] < 2:
        raise ValueError("x 的样本数 N 必须 >= 2")

    labels = doc["labels"]
    _require_list(labels, "labels")
    if len(labels) != x_shape[0]:
        raise ValueError(
            "labels 长度 %d 与 x 样本数 %d 不符"
            % (len(labels), x_shape[0])
