        if isinstance(label, list):
            raise ValueError("labels 的层级过深：标量位置出现了 list")
        if isinstance(label, bool) or not isinstance(label, int):
            raise TypeError(
                "labels 的元素必须是 int（拒绝 bool），得到 %s"
                % type(label).__name__
            )
        if label not in (0, 1):
            raise ValueError("labels 的元素必须为 0 或 1")
    return x, labels


